 3→import { useState } from "react";
 4→import { useRouter, useSearchParams } from "next/navigation";
 5→
 6→export function LoginForm() {
 7→  const router = useRouter();
 8→  const searchParams = useSearchParams();
 9→  const [username, setUsername] = useState("");
10→  const [password, setPassword] = useState("");
11→  const [error, setError] = useState("");
12→  const [loading, setLoading] = useState(false);
13→
14→  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
15→    event.preventDefault();
16→    setLoading(true);
17→    setError("");
18→
19→    try {
20→      const response = await fetch("/api/auth/login", {
21→        method: "POST",
22→        headers: { "Content-Type": "application/json" },
23→        body: JSON.stringify({ username, password }),
24→      });
25→
26→      if (!response.ok) {
27→        const data = (await response.json()) as { message?: string };
28→        throw new Error(data.message ?? "로그인에 실패했습니다.");
29→      }
30→
31→      router.push(searchParams.get("next") ?? "/");
32→      router.refresh();
33→    } catch (caught) {
34→      setError(caught instanceof Error ? caught.message : "로그인에 실패했습니다.");
35→    } finally {
36→      setLoading(false);
37→    }
38→  }
39→
40→  return (
41→    <form onSubmit={handleSubmit} className="space-y-5">
42→      <label className="block space-y-2">
43→        <span style={{ fontSize: 13, fontWeight: 500, color: "var(--text-body)" }}>아이디</span>
44→        <input
45→          value={username}
46→          onChange={(event) => setUsername(event.target.value)}
47→          className="input"
48→          style={{ width: "100%", padding: "10px 14px", fontSize: 13, borderRadius: 8 }}
49→          placeholder="username"
50→          autoComplete="username"
51→        />
52→      </label>
53→      <label className="block space-y-2">
54→        <span style={{ fontSize: 13, fontWeight: 500, color: "var(--text-body)" }}>비밀번호</span>
55→        <input
56→          type="password"
57→          value={password}
58→          onChange={(event) => setPassword(event.target.value)}
59→          className="input"
60→          style={{ width: "100%", padding: "10px 14px", fontSize: 13, borderRadius: 8 }}
61→          placeholder="password"
62→          autoComplete="current-password"
63→        />
64→      </label>
65→
66→      {error ? (
67→        <p style={{
68→          background: "#fdeaea",
69→          color: "#c0392b",
70→          padding: "10px 14px",
71→          borderRadius: 8,
72→          fontSize: 13,
73→        }}>
74→          {error}
75→        </p>
76→      ) : null}
77→
78→      <button
79→        type="submit"
80→        disabled={loading}
81→        style={{
82→          width: "100%",
83→          padding: "11px 14px",
84→          background: "#0a1f14",
85→          color: "#fff",
86→          border: "none",
87→          borderRadius: 8,
88→          fontSize: 14,
89→          fontWeight: 600,
90→          cursor: loading ? "not-allowed" : "pointer",
91→          opacity: loading ? 0.7 : 1,
92→        }}
93→      >
94→        {loading ? "로그인 중..." : "로그인"}
95→      </button>
96→    </form>
97→  );
98→}
