 1→import { NextResponse } from "next/server";
 2→import {
 3→  attachSessionCookie,
 4→  createSession,
 5→  getUserByUsername,
 6→} from "@/lib/auth";
 7→import { verifyPassword } from "@/lib/password";
 8→
 9→export async function POST(request: Request) {
10→  const body = (await request.json()) as { username?: string; password?: string };
11→  if (!body.username || !body.password) {
12→    return NextResponse.json({ message: "username and password are required" }, { status: 400 });
13→  }
14→
15→  const user = getUserByUsername(body.username);
16→  if (!user || !verifyPassword(body.password, user.password)) {
17→    return NextResponse.json({ message: "로그인 정보가 올바르지 않습니다." }, { status: 401 });
18→  }
19→
20→  const session = createSession(user.id);
21→  const response = NextResponse.json({
22→    user: {
23→      id: user.id,
24→      username: user.username,
25→      role: user.role,
26→      departmentCode: user.departmentCode,
27→    },
28→  });
29→
30→  attachSessionCookie(response, session.token, session.expiresAt);
31→  return response;
32→}
